//! Opt-in scripted interaction profile (`MATERIAL_PROFILE_SCRIPT=interactions`
//! with `MATERIAL_PROFILE_OUTPUT=<frames.json>`): page switches between
//! Button, Text field, Date picker and Examples, hover and press in the
//! Button preview, and continuous wheel scrolling of Overview and a Specs
//! tab. It reads upstream's own profiler (`gpui-kit/profiler`): every frame's
//! `FrameEvent::Draw` and the `FrameEvent::Present` that submitted it are kept
//! raw and labelled with the step that was active when the draw started;
//! `page_switch_ns` holds the first frame after each switch. A frame's time is
//! its draw plus its submission: the platform callback around them (input
//! dispatch, cleanup) and the GPU are not timed. Never enabled by the ordinary
//! gallery (`scripts/profile-gallery.py` summarizes it).
use super::{Gallery, Tab, catalog};
use gpui::{
    profiler::{self, FrameEvent, FrameTimingCollector},
    *,
};
use serde_json::{Value, json};
use std::{
    cell::RefCell,
    path::PathBuf,
    rc::Rc,
    time::{Duration, Instant},
};

/// What a step does when it starts.
#[derive(Clone, Copy)]
enum Action {
    Navigate(&'static str),
    Tab(Tab),
    Move(f32, f32),
    Press(f32, f32),
    Release(f32, f32),
    /// Wheel 8 px per frame for the step, down then up.
    Scroll,
}

type Step = (&'static str, Action, u64);

/// The script: an action, then this much time before the next step.
const SCRIPT: &[Step] = &[
    ("switch:button", Action::Navigate("button"), 900),
    ("hover:enter", Action::Move(582., 492.), 700),
    ("press:down", Action::Press(582., 492.), 500),
    ("press:up", Action::Release(582., 492.), 700),
    ("hover:leave", Action::Move(700., 700.), 700),
    ("switch:text-field", Action::Navigate("text-field"), 900),
    ("switch:date-picker", Action::Navigate("date-picker"), 900),
    ("switch:examples", Action::Navigate("examples"), 900),
    ("switch:button-again", Action::Navigate("button"), 700),
    ("switch:overview", Action::Navigate("overview"), 700),
    ("scroll:overview", Action::Scroll, 3000),
    ("switch:button-specs", Action::Navigate("button"), 500),
    ("switch:tab-specs", Action::Tab(Tab::Specs), 900),
    ("scroll:specs", Action::Scroll, 3000),
    ("idle", Action::Move(700., 700.), 1000),
];

/// Profiling aids for a sampler: one interaction repeated for ~10 s.
const HOVER: &[Step] = &[
    ("hover:enter", Action::Move(582., 492.), 500),
    ("press:down", Action::Press(582., 492.), 400),
    ("press:up", Action::Release(582., 492.), 500),
    ("hover:leave", Action::Move(700., 700.), 500),
];
const SWITCH: &[Step] = &[
    ("switch:text-field", Action::Navigate("text-field"), 400),
    ("switch:date-picker", Action::Navigate("date-picker"), 400),
    ("switch:examples", Action::Navigate("examples"), 400),
    ("switch:button", Action::Navigate("button"), 400),
];

/// `interactions` runs [`SCRIPT`] once; `hover`, `switch`, `scroll-specs`
/// and `scroll-overview` repeat one interaction.
fn script(name: &str) -> Option<Vec<Step>> {
    let repeat = |lead: &[Step], body: &[Step], times: usize| {
        let mut steps = lead.to_vec();
        for _ in 0..times {
            steps.extend_from_slice(body);
        }
        steps
    };
    Some(match name {
        "interactions" => SCRIPT.to_vec(),
        "hover" => repeat(
            &[("switch:button", Action::Navigate("button"), 600)],
            HOVER,
            6,
        ),
        "switch" => repeat(&[], SWITCH, 6),
        "scroll-specs" => repeat(
            &[
                ("switch:button", Action::Navigate("button"), 300),
                ("switch:tab-specs", Action::Tab(Tab::Specs), 600),
            ],
            &[("scroll:specs", Action::Scroll, 3000)],
            4,
        ),
        "scroll-overview" => repeat(&[], &[("scroll:overview", Action::Scroll, 3000)], 4),
        _ => return None,
    })
}

pub struct Session {
    steps: Vec<Step>,
    output: PathBuf,
    collector: FrameTimingCollector,
}

/// Must run before the window opens so the initial draw is collected.
pub fn prepare() -> Option<Session> {
    let steps = script(&std::env::var("MATERIAL_PROFILE_SCRIPT").ok()?)?;
    let output = std::env::var_os("MATERIAL_PROFILE_OUTPUT")?;
    profiler::set_trace_enabled(true);
    Some(Session {
        steps,
        output: output.into(),
        collector: FrameTimingCollector::new(),
    })
}

fn dispatch(window: &mut Window, cx: &mut App, input: PlatformInput) {
    window.dispatch_event(input, cx);
}

fn scroll_frames(
    window: &mut Window,
    cx: &mut App,
    list: ListState,
    down: Rc<RefCell<bool>>,
    end: Instant,
    moved: Rc<RefCell<Vec<f32>>>,
) {
    if Instant::now() >= end {
        return;
    }
    let half = end - Duration::from_millis(1500);
    let going_down = Instant::now() < half && *down.borrow();
    let position = point(px(800.), px(500.));
    let before = list.scroll_px_offset_for_scrollbar().y;
    dispatch(
        window,
        cx,
        PlatformInput::Scroll(ScrollEvent {
            position,
            delta: ScrollDelta::Pixels(point(px(0.), px(if going_down { -8. } else { 8. }))),
            ..Default::default()
        }),
    );
    let after = list.scroll_px_offset_for_scrollbar().y;
    moved.borrow_mut().push(f32::from(after - before));
    window.on_next_frame(move |window, cx| scroll_frames(window, cx, list, down, end, moved));
}

impl Session {
    pub fn install(mut self, gallery: Entity<Gallery>, window: &mut Window, cx: &mut App) {
        let handle = window.window_handle();
        let window_id = handle.window_id();
        let origin = Instant::now();
        let marks: Rc<RefCell<Vec<(&'static str, Instant)>>> = Default::default();
        let moved: Rc<RefCell<Vec<f32>>> = Default::default();
        cx.spawn(async move |cx| {
            let executor = cx.background_executor().clone();
            let mut events: Vec<FrameEvent> = Vec::new();
            executor.timer(Duration::from_millis(1500)).await;
            let steps = std::mem::take(&mut self.steps);
            for (label, action, wait) in steps {
                let gallery = gallery.clone();
                let marks = marks.clone();
                let moved = moved.clone();
                let _ = handle.update(cx, move |_, window, cx| {
                    marks.borrow_mut().push((label, Instant::now()));
                    match action {
                        Action::Navigate(id) => {
                            let entry = catalog::position(id).expect("catalog entry");
                            gallery.update(cx, |gallery, cx| gallery.navigate(entry, cx));
                        }
                        Action::Tab(tab) => {
                            gallery.update(cx, |gallery, cx| gallery.set_tab(tab, cx))
                        }
                        Action::Move(x, y) => dispatch(
                            window,
                            cx,
                            PlatformInput::MouseMove(MouseMoveEvent {
                                position: point(px(x), px(y)),
                                ..Default::default()
                            }),
                        ),
                        Action::Press(x, y) => dispatch(
                            window,
                            cx,
                            PlatformInput::MouseDown(MouseDownEvent {
                                button: MouseButton::Left,
                                position: point(px(x), px(y)),
                                click_count: 1,
                                ..Default::default()
                            }),
                        ),
                        Action::Release(x, y) => dispatch(
                            window,
                            cx,
                            PlatformInput::MouseUp(MouseUpEvent {
                                button: MouseButton::Left,
                                position: point(px(x), px(y)),
                                click_count: 1,
                                ..Default::default()
                            }),
                        ),
                        Action::Scroll => {
                            let list = gallery.read(cx).list.clone();
                            let end = Instant::now() + Duration::from_millis(wait);
                            scroll_frames(
                                window,
                                cx,
                                list,
                                Rc::new(RefCell::new(true)),
                                end,
                                moved,
                            );
                        }
                    }
                });
                executor.timer(Duration::from_millis(wait)).await;
                events.extend(self.collector.collect_unseen());
            }
            profiler::set_trace_enabled(false);
            let report = report(events, window_id, origin, &marks.borrow(), &moved.borrow());
            if let Some(parent) = self.output.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            std::fs::write(&self.output, serde_json::to_vec_pretty(&report).unwrap())
                .expect("write interaction profile");
            eprintln!("Interaction profile: {}", self.output.display());
            std::process::exit(0);
        })
        .detach();
    }
}

fn report(
    events: Vec<FrameEvent>,
    window_id: WindowId,
    origin: Instant,
    marks: &[(&'static str, Instant)],
    moved: &[f32],
) -> Value {
    let ns = |at: Instant| -> i128 {
        if at >= origin {
            (at - origin).as_nanos() as i128
        } else {
            -((origin - at).as_nanos() as i128)
        }
    };
    let step_at = |at: Instant| -> &'static str {
        marks
            .iter()
            .rev()
            .find(|(_, mark)| *mark <= at)
            .map_or("startup", |(label, _)| label)
    };
    let frames = frames(&events, window_id);
    let rows: Vec<Value> = frames
        .iter()
        .enumerate()
        .map(|(index, frame)| {
            let draw = &frame.draw;
            json!({
                "initial": index == 0,
                "step": step_at(draw.draw_start),
                "start_ns": ns(draw.draw_start),
                "frame_ns": frame.cpu().as_nanos(),
                "draw_ns": draw.draw_duration().as_nanos(),
                "present_ns": frame.present.map(|present| present.present_duration().as_nanos()),
                "phases": {
                    "request_layout_ns": draw.phases.request_layout.as_nanos(),
                    "prepaint_ns": draw.phases.prepaint.as_nanos(),
                    "paint_ns": draw.phases.paint.as_nanos(),
                },
            })
        })
        .collect();
    // The first frame after each switch is that switch's cost.
    let mut switches = Vec::new();
    for (label, at) in marks {
        if !label.starts_with("switch:") {
            continue;
        }
        if let Some(frame) = frames.iter().find(|frame| frame.draw.draw_start >= *at) {
            switches.push(json!({"step": label, "frame_ns": frame.cpu().as_nanos()}));
        }
    }
    json!({
        "schema": "gallery-interactions-v2",
        "metadata": {
            "release": !cfg!(debug_assertions),
            "backend": if gpui_kit::GPUI_FAST { "gpui-fast" } else { "gpui-pre" },
            "load_average_at_end": std::process::Command::new("sysctl").args(["-n", "vm.loadavg"]).output().ok().map(|o| String::from_utf8_lossy(&o.stdout).trim().to_owned()),
            "script": std::env::var("MATERIAL_PROFILE_SCRIPT").ok(), "interactions_script": SCRIPT.iter().map(|(label, _, wait)| json!([label, wait])).collect::<Vec<_>>(),
            "frame_definition": "upstream profiler: Window::draw (render, layout, prepaint, paint) plus the platform submission of that draw, when there was one; the frame callback around them, drawable waits outside the submission and GPU time are not measured",
        },
        "marks_ns": marks.iter().map(|(label, at)| json!([label, ns(*at)])).collect::<Vec<_>>(),
        "scroll_moved_px": moved,
        "page_switch_ns": switches.iter().map(|s| s["frame_ns"].clone()).collect::<Vec<_>>(),
        "page_switches": switches,
        "frames": rows,
    })
}

/// A drawn frame and the submission of what it drew, if it was submitted.
struct Frame {
    draw: profiler::FrameTiming,
    present: Option<profiler::PresentTiming>,
}

impl Frame {
    fn cpu(&self) -> Duration {
        self.draw.draw_duration()
            + self
                .present
                .map_or(Duration::ZERO, |present| present.present_duration())
    }
}

/// `window`'s draws in order, each with the first submission that began after it
/// ended and before the next draw.
fn frames(events: &[FrameEvent], window: WindowId) -> Vec<Frame> {
    let mut frames: Vec<Frame> = Vec::new();
    for event in events {
        match event {
            FrameEvent::Draw(draw) if draw.window_id == window => frames.push(Frame {
                draw: *draw,
                present: None,
            }),
            FrameEvent::Present(present) if present.window_id == window => {
                if let Some(frame) = frames.last_mut()
                    && frame.present.is_none()
                    && present.present_start >= frame.draw.draw_end
                {
                    frame.present = Some(*present);
                }
            }
            _ => {}
        }
    }
    frames
}

#[cfg(test)]
mod tests {
    use super::*;
    use core::prelude::v1::test;
    use gpui::profiler::{DrawPhases, FrameTiming, PresentTiming};

    #[test]
    fn a_frame_is_its_draw_and_the_submission_after_it() {
        let window = WindowId::from(1);
        let at = Instant::now();
        let ms = |n: u64| at + Duration::from_millis(n);
        let draw = |start, end| {
            FrameEvent::Draw(FrameTiming {
                window_id: window,
                dirty_at: None,
                invalidations: 1,
                draw_start: ms(start),
                draw_end: ms(end),
                refresh_interval: None,
                signal_at: None,
                phases: DrawPhases::default(),
            })
        };
        let present = |start, end| {
            FrameEvent::Present(PresentTiming {
                window_id: window,
                present_start: ms(start),
                present_end: ms(end),
                animation_interval: None,
            })
        };
        // A draw that was not submitted, then one that was, then a second
        // submission of the same draw, which is not a frame's.
        let frames = frames(
            &[draw(0, 2), draw(10, 13), present(13, 14), present(20, 21)],
            window,
        );
        assert_eq!(frames.len(), 2);
        assert_eq!(frames[0].cpu(), Duration::from_millis(2));
        assert_eq!(frames[1].cpu(), Duration::from_millis(4));
    }
}

//! The focus ring and ripple every interactive component paints, whichever feature
//! group it is in; so this module, unlike the button that first needed them, is always
//! compiled.
mod focus_ring;
pub(crate) mod ripple;
mod ripple_clip;
pub(crate) use focus_ring::{ButtonFocusRing, RingLayer};
#[cfg(test)]
pub(crate) use focus_ring::{LAYERED_RING, PAINTED_RING_CHILDREN};
pub(crate) use ripple::ButtonRipple;
#[cfg(test)]
pub(crate) use ripple::{last_wave_corners, ripple_writes, waves_painted};

//! Paint the M3 focus indicator around (or, for tightly connected items,
//! inside) a control without changing layout or hitboxes.
//!
//! The indicator is 3dp of secondary. Standalone controls use the M3 outer
//! offset (2dp outside the border box). Items packed edge to edge, such as
//! connected tiles, use the M3 inner offset (3dp inside) so a neighbour
//! painted later cannot cover it. Where the item's own fill can be primary,
//! as a selected connected button group option is, an inner secondary ring
//! cannot be seen; such a group keeps the outer offset and hands its rings to
//! a [`RingLayer`] that it paints after every item.
use crate::{color::ColorRole, theme::color};
use gpui::*;

/// M3 focus indicator thickness.
pub(crate) const RING_WIDTH: Pixels = px(3.);
/// M3 focus indicator outer offset: the gap between the border box and the ring.
pub(crate) const OUTER_OFFSET: Pixels = px(2.);
/// M3 focus indicator inner offset: how far inside the border box the ring's
/// outer edge sits.
pub(crate) const INNER_OFFSET: Pixels = px(3.);

enum Visibility {
    /// Visible while this handle has keyboard focus.
    Focus(FocusHandle),
    /// Visible while the caller's resolved state says focus is inside, e.g. a
    /// wrapper around a component whose own focus handle is private.
    Resolved(bool),
}

enum Radius {
    Rems(Rems),
    Corners(Corners<Pixels>),
}

pub(crate) struct ButtonFocusRing {
    child: AnyElement,
    visibility: Visibility,
    enabled: bool,
    radius: Radius,
    inward: bool,
    /// Where the ring is painted instead of in place, when set.
    layer: Option<RingLayer>,
    /// A specimen's forced focus: shown regardless of input modality.
    forced: bool,
    #[cfg(test)]
    observed: Option<std::rc::Rc<std::cell::Cell<Option<Bounds<Pixels>>>>>,
    #[cfg(test)]
    observed_corners: Option<std::rc::Rc<std::cell::Cell<Option<Corners<Pixels>>>>>,
}
impl ButtonFocusRing {
    pub(crate) fn new(
        child: impl IntoElement,
        focus: FocusHandle,
        enabled: bool,
        radius: Rems,
    ) -> Self {
        Self {
            child: child.into_any_element(),
            visibility: Visibility::Focus(focus),
            enabled,
            radius: Radius::Rems(radius),
            inward: false,
            layer: None,
            forced: false,
            #[cfg(test)]
            observed: None,
            #[cfg(test)]
            observed_corners: None,
        }
    }

    /// The outer ring around a control whose border box has these corners.
    pub(crate) fn with_corners(
        child: impl IntoElement,
        focus: FocusHandle,
        enabled: bool,
        corners: Corners<Pixels>,
    ) -> Self {
        Self {
            radius: Radius::Corners(corners),
            ..Self::new(child, focus, enabled, Rems(0.))
        }
    }

    /// The outer ring, shown while `active` (focus resolved by the caller to
    /// be inside the child) and the last input came from the keyboard.
    pub(crate) fn resolved(child: impl IntoElement, active: bool, radius: Rems) -> Self {
        Self {
            child: child.into_any_element(),
            visibility: Visibility::Resolved(active),
            enabled: true,
            radius: Radius::Rems(radius),
            inward: false,
            layer: None,
            forced: false,
            #[cfg(test)]
            observed: None,
            #[cfg(test)]
            observed_corners: None,
        }
    }

    /// Always draw the ring (while enabled), for a static focused specimen.
    pub(crate) fn forced(mut self, forced: bool) -> Self {
        self.forced = forced;
        self
    }

    /// Draw the ring at the M3 inner offset instead of the outer one.
    pub(crate) fn inward(mut self) -> Self {
        self.inward = true;
        self
    }

    /// Hand the ring to `layer`, which paints it after its later siblings,
    /// instead of painting it in place, where they would cover an outer ring.
    pub(crate) fn painted_by(mut self, layer: &RingLayer) -> Self {
        self.layer = Some(layer.clone());
        self
    }

    #[cfg(test)]
    pub(crate) fn observe(
        mut self,
        observed: std::rc::Rc<std::cell::Cell<Option<Bounds<Pixels>>>>,
    ) -> Self {
        self.observed = Some(observed);
        self
    }
}

/// Ring bounds and corner radii for a border box with `corners`.
pub(crate) fn ring_geometry(
    bounds: Bounds<Pixels>,
    corners: Corners<Pixels>,
    inward: bool,
) -> (Bounds<Pixels>, Corners<Pixels>) {
    if inward {
        let ring = bounds.inset(INNER_OFFSET);
        let shrink = |radius: Pixels| (radius - INNER_OFFSET).max(px(0.));
        let corners = Corners {
            top_left: shrink(corners.top_left),
            top_right: shrink(corners.top_right),
            bottom_right: shrink(corners.bottom_right),
            bottom_left: shrink(corners.bottom_left),
        };
        (ring, corners.clamp_radii_for_quad_size(ring.size))
    } else {
        let grow = OUTER_OFFSET + RING_WIDTH;
        let ring = bounds.dilate(grow);
        let corners = Corners {
            top_left: corners.top_left + grow,
            top_right: corners.top_right + grow,
            bottom_right: corners.bottom_right + grow,
            bottom_left: corners.bottom_left + grow,
        };
        (ring, corners.clamp_radii_for_quad_size(ring.size))
    }
}

impl IntoElement for ButtonFocusRing {
    type Element = Self;
    fn into_element(self) -> Self {
        self
    }
}
impl Element for ButtonFocusRing {
    type RequestLayoutState = ();
    type PrepaintState = ();
    fn id(&self) -> Option<ElementId> {
        None
    }
    fn source_location(&self) -> Option<&'static std::panic::Location<'static>> {
        None
    }
    fn request_layout(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        window: &mut Window,
        cx: &mut App,
    ) -> (LayoutId, ()) {
        (self.child.request_layout(window, cx), ())
    }
    fn prepaint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        _: Bounds<Pixels>,
        _: &mut (),
        window: &mut Window,
        cx: &mut App,
    ) {
        self.child.prepaint(window, cx);
    }
    fn paint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        bounds: Bounds<Pixels>,
        _: &mut (),
        _: &mut (),
        window: &mut Window,
        cx: &mut App,
    ) {
        self.child.paint(window, cx);
        let focused = match &self.visibility {
            Visibility::Focus(focus) => focus.is_focused(window),
            Visibility::Resolved(active) => *active,
        };
        let visible =
            self.enabled && (self.forced || (focused && window.last_input_was_keyboard()));
        let corners = match self.radius {
            Radius::Rems(radius) => Corners::all(radius.to_pixels(window.rem_size())),
            Radius::Corners(corners) => corners,
        };
        #[cfg(test)]
        if let Some(observed) = &self.observed_corners {
            observed.set(Some(corners));
        }
        let (ring_bounds, ring_corners) = ring_geometry(bounds, corners, self.inward);
        #[cfg(test)]
        if let Some(observed) = &self.observed {
            observed.set(visible.then_some(ring_bounds));
        }
        #[cfg(test)]
        PAINTED_RING_CHILDREN.with(|count| count.set(count.get() + 1));
        if visible {
            match &self.layer {
                Some(layer) => layer.ring.set(Some((ring_bounds, ring_corners))),
                None => paint_ring(ring_bounds, ring_corners, window),
            }
        }
    }
}

fn paint_ring(bounds: Bounds<Pixels>, corners: Corners<Pixels>, window: &mut Window) {
    window.paint_quad(
        outline(bounds, color(ColorRole::SECONDARY), BorderStyle::Solid)
            .border_widths(RING_WIDTH)
            .corner_radii(corners),
    );
}

#[cfg(test)]
thread_local! {
    /// How many rings' children have painted, for checking a layer's order.
    pub(crate) static PAINTED_RING_CHILDREN: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    /// The last ring a layer painted, and how many rings' children had
    /// painted before it.
    pub(crate) static LAYERED_RING: std::cell::Cell<Option<(Bounds<Pixels>, usize)>> =
        const { std::cell::Cell::new(None) };
}

/// A ring handed to a [`RingLayer`]: its bounds and corners, until painted.
type PendingRing = std::rc::Rc<std::cell::Cell<Option<(Bounds<Pixels>, Corners<Pixels>)>>>;

/// Paints, above a group of tightly packed items, the focus ring that one of
/// them hands it with [`ButtonFocusRing::painted_by`]. Make one per render and
/// add [`RingLayer::element`] to the group after every item: it is absolutely
/// positioned and takes no space. The ring stays in the group's paint order and
/// content mask, so overlays opened above the group still cover it.
#[derive(Clone, Default)]
pub(crate) struct RingLayer {
    ring: PendingRing,
}

impl RingLayer {
    pub(crate) fn element(&self) -> RingLayerElement {
        RingLayerElement {
            ring: self.ring.clone(),
        }
    }
}

pub(crate) struct RingLayerElement {
    ring: PendingRing,
}

impl IntoElement for RingLayerElement {
    type Element = Self;
    fn into_element(self) -> Self {
        self
    }
}

impl Element for RingLayerElement {
    type RequestLayoutState = ();
    type PrepaintState = ();
    fn id(&self) -> Option<ElementId> {
        None
    }
    fn source_location(&self) -> Option<&'static std::panic::Location<'static>> {
        None
    }
    fn request_layout(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        window: &mut Window,
        cx: &mut App,
    ) -> (LayoutId, ()) {
        let style = Style {
            position: Position::Absolute,
            size: size(px(0.).into(), px(0.).into()),
            ..Style::default()
        };
        (window.request_layout(style, [], cx), ())
    }
    fn prepaint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        _: Bounds<Pixels>,
        _: &mut (),
        _: &mut Window,
        _: &mut App,
    ) {
    }
    fn paint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        _: Bounds<Pixels>,
        _: &mut (),
        _: &mut (),
        window: &mut Window,
        _: &mut App,
    ) {
        // Taken, so a ring from an earlier frame is never painted again.
        let ring = self.ring.take();
        #[cfg(test)]
        LAYERED_RING.with(|layered| {
            layered.set(
                ring.map(|(bounds, _)| (bounds, PAINTED_RING_CHILDREN.with(|count| count.get()))),
            )
        });
        if let Some((bounds, corners)) = ring {
            paint_ring(bounds, corners, window);
        }
    }
}

